def conservar_saldos(apps, schema_editor):
    Cuenta = apps.get_model("patrimonio", "CuentaPorCobrar")
    Calculo = apps.get_model("patrimonio", "CalculoCuentaPorCobrar")
    using = schema_editor.connection.alias
    for cuenta in Cuenta.objects.using(using).iterator():
        detalles = list(cuenta.detalles.using(using).all())
        abonos = list(cuenta.abonos.using(using).all())
        cargos = sum((d.monto for d in detalles), Decimal("0"))
        pagos = sum((a.monto for a in abonos), Decimal("0"))
        entradas, contabilizados = [], {}
        for tipo, registros, prefijo in [("CARGO", detalles, "detalle"), ("ABONO", abonos, "abono")]:
            for registro in registros:
                clave = f"{prefijo}:{registro.pk}"
                efecto = registro.monto if tipo == "CARGO" else -registro.monto
                contabilizados[clave] = str(efecto)
                entrada = dict(tipo=tipo, clave=clave, descripcion=registro.descripcion,
                               fecha=registro.fecha.isoformat(), monto=str(registro.monto),
                               efecto=str(efecto), decision="REFERENCIA")
                if registro.movimiento_id:
                    entrada["movimiento_id"] = registro.movimiento_id
                    contabilizados[f"movimiento:{registro.movimiento_id}"] = "0"
                if tipo == "CARGO" and registro.evento_externo_id:
                    entrada["evento_externo_id"] = registro.evento_externo_id
                    contabilizados[f"neat:{registro.evento_externo_id}"] = "0"
                entradas.append(entrada)
        saldo = max(cargos - pagos, Decimal("0"))
        periodo = max((d.periodo for d in detalles), default=timezone.localdate().replace(day=1))
        moneda = cuenta.moneda
        importe = f"US${saldo:,.2f}" if moneda == "USD" else "$" + f"{saldo:,.0f}".replace(",", ".")
        Calculo.objects.using(using).create(
            cuenta=cuenta, periodo=periodo, revision=1, estado="REFERENCIA",
            fecha_calculo=timezone.localdate(), cargos=cargos, abonos=pagos, saldo_final=saldo,
            desglose={"entradas": entradas, "contabilizados": contabilizados},
            texto=f"Detalle pendiente: {cuenta.nombre}\nTotal pendiente: {importe}",
        )


